 "content": "def transform(grid):
    """Replace large monochrome rectangular patches with marker color 4."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # Every intended patch contains at least four rows and four columns;
    # using every qualifying rectangle also handles patches embedded in noise.
    for top in range(h):
        for bottom in range(top + 3, h):
            common = [grid[top][c] if all(grid[r][c] == grid[top][c] for r in range(top, bottom + 1)) else None for c in range(w)]
            c = 0
            while c < w:
                color = common[c]
                if color is None:
                    c += 1
                    continue
                end = c + 1
                while end < w and common[end] == color:
                    end += 1
                if end - c >= 4:
                    for r in range(top, bottom + 1):
                        for cc in range(c, end):
                            marked[r][cc] = True
                c = end
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
